{"version":3,"isGlobalStylesUserThemeJSON":true,"settings":{"layout":{"contentSize":"720px","wideSize":"1280px"},"color":{"palette":[{"slug":"base","name":"Paper","color":"#f7f5ed"},{"slug":"contrast","name":"Forest","color":"#243e33"},{"slug":"accent-1","name":"Moss","color":"#e4e8dc"},{"slug":"accent-2","name":"Clay","color":"#a95534"},{"slug":"accent-3","name":"Deep forest","color":"#1c3028"},{"slug":"accent-4","name":"Stone","color":"#565d52"},{"slug":"accent-5","name":"White","color":"#ffffff"}]},"typography":{"fontFamilies":[{"name":"Manrope","slug":"manrope","fontFamily":"Manrope, sans-serif","fontFace":[{"src":["{{site_url}}/wp-content/themes/twentytwentyfive/assets/fonts/manrope/Manrope-VariableFont_wght.woff2"],"fontWeight":"200 800","fontStyle":"normal","fontFamily":"Manrope"}]},{"name":"Fira Code","slug":"fira-code","fontFamily":""Fira Code", monospace","fontFace":[{"src":["{{site_url}}/wp-content/themes/twentytwentyfive/assets/fonts/fira-code/FiraCode-VariableFont_wght.woff2"],"fontWeight":"300 700","fontStyle":"normal","fontFamily":""Fira Code""}]},{"name":"Vollkorn","slug":"vollkorn","fontFamily":"Vollkorn, Georgia, serif","fontFace":[{"fontFamily":"Vollkorn","fontWeight":"400 900","fontStyle":"normal","src":["{{site_url}}/wp-content/themes/twentytwentyfive/assets/fonts/vollkorn/Vollkorn-VariableFont_wght.woff2"]},{"fontFamily":"Vollkorn","fontWeight":"400 900","fontStyle":"italic","src":["{{site_url}}/wp-content/themes/twentytwentyfive/assets/fonts/vollkorn/Vollkorn-Italic-VariableFont_wght.woff2"]}]}]}},"styles":{"color":{"background":"#f7f5ed","text":"#243e33"},"typography":{"fontFamily":"var:preset|font-family|manrope","fontSize":"17px","fontWeight":"400","lineHeight":"1.7"},"spacing":{"blockGap":"1.5rem","padding":{"top":"0","right":"0","bottom":"0","left":"0"}},"elements":{"heading":{"typography":{"fontFamily":"var:preset|font-family|vollkorn","fontWeight":"400","lineHeight":"1.08","letterSpacing":"-0.035em"}},"link":{"color":{"text":"#243e33"},"typography":{"textDecoration":"none"},":hover":{"typography":{"textDecoration":"underline"}}},"button":{"color":{"background":"#243e33","text":"#f7f5ed"},"border":{"radius":"0"},"typography":{"fontFamily":"var:preset|font-family|manrope","fontSize":"16px","fontWeight":"600","lineHeight":"1.3"},"spacing":{"padding":{"top":"16px","right":"30px","bottom":"16px","left":"30px"}}}},"css":":root {
  --fn-paper: #f7f5ed;
  --fn-moss: #e4e8dc;
  --fn-forest: #243e33;
  --fn-deep: #1c3028;
  --fn-stone: #565d52;
  --fn-clay: #a95534;
  --fn-clay-light: #e3a07f;
  --fn-mist: #c9d2c4;
  --fn-line: #243e332e;
  --fn-serif: var(--wp--preset--font-family--vollkorn);
  --fn-mono: var(--wp--preset--font-family--fira-code);
  --fn-gutter: 56px;
  --fn-shell: min(1280px, calc(100vw - 2 * var(--fn-gutter)));
}
/* The footer script adds fn-smooth after load, so arriving at /#copy jumps and clicks on the page glide */
html.fn-smooth { scroll-behavior: smooth; }
body { -webkit-font-smoothing: antialiased; overflow-x: clip; }
body .wp-site-blocks { padding: 0; }
.wp-site-blocks > * { margin-block-start: 0; }
.fn-shell { width: var(--fn-shell); max-width: 1280px; margin-inline: auto; }
.fn-main { margin-block: 0; }
.fn-main > .wp-block-post-content, .fn-main > .wp-block-post-content > * { margin-block: 0; }
a { text-underline-offset: .2em; text-decoration-thickness: 1px; }
a:focus-visible, button:focus-visible { outline: 2px solid var(--fn-clay); outline-offset: 4px; }
h1 em, h2 em { color: var(--fn-clay); }

/* Header */
.fn-header { min-height: 92px; gap: 32px; border-bottom: 1px solid var(--fn-line); }
.fn-brand { gap: 10px; align-items: center; }
.fn-mark { margin: 0; color: var(--fn-clay); font: 400 34px/1 Georgia, serif; }
.fn-wordmark { margin: 0; font-family: var(--fn-serif); font-size: 32px; font-weight: 600; letter-spacing: -.045em; line-height: 1; white-space: nowrap; }
.fn-wordmark a:hover { text-decoration: none; }
.fn-nav { font-size: 15px; font-weight: 600; }
.fn-nav .wp-block-navigation__container { gap: 36px; }
.fn-nav .wp-block-navigation-item:last-child a { border: 1.5px solid var(--fn-forest); padding: 10px 20px; }
.fn-nav .wp-block-navigation-item:last-child a:hover { background: var(--fn-forest); color: var(--fn-paper); text-decoration: none; }

/* Shared pieces */
.wp-block-button__link:hover { background: var(--fn-deep); }
.fn-text-link { margin: 0; font-size: 15px; font-weight: 600; }
.fn-text-link a { border-bottom: 1.5px solid currentColor; padding-bottom: 3px; }
.fn-text-link a::after { content: " →"; }
.fn-text-link a:hover { text-decoration: none; color: var(--fn-clay); }

/* Home: the headline and the way to copy on the left, one story's photograph on the right, out to the window's edge */
.fn-hero { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: 64px; align-items: center; padding: 40px 0 120px; }
.fn-hero > *, .fn-hero-copy > * { margin: 0; }
.fn-hero-title { font-size: clamp(64px, 8.4vw, 132px); line-height: .92; letter-spacing: -.045em; }
.fn-hero-title em { font-style: italic; }
.fn-hero-copy .fn-hero-description { margin-top: 36px; max-width: 30em; font-size: 20px; line-height: 1.6; color: var(--fn-stone); }
.fn-hero-copy .fn-actions { margin-top: 40px; gap: 14px 24px; }
.fn-actions > * { margin: 0; }
.fn-or-link { font-size: 16px; color: var(--fn-stone); }
.fn-or-link a { font-weight: 600; color: var(--fn-forest); text-decoration: underline; }
.fn-or-link a:hover { color: var(--fn-clay); }
.fn-hero-image.wp-block-image { position: relative; margin-right: calc((var(--fn-shell) - 100vw) / 2); }
.fn-hero-image.wp-block-image a { display: block; }
.fn-hero-image.wp-block-image img { display: block; width: 100%; height: clamp(520px, calc(100vh - 172px), 820px); object-fit: cover; object-position: 50% 40%; }
.fn-hero-image .wp-element-caption { position: absolute; left: 0; bottom: 0; margin: 0; padding: 16px 22px; max-width: calc(100% - 48px); background: var(--fn-paper); color: var(--fn-stone); font-size: 15px; line-height: 1.4; text-align: left; }
.fn-hero-image .wp-element-caption a { display: block; margin-top: 2px; font-family: var(--fn-serif); font-size: 22px; letter-spacing: -.02em; color: var(--fn-forest); }

/* Story cards */
.fn-front { padding-bottom: 128px; }
.fn-section-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 24px; margin: 0 0 48px; padding-top: 28px; border-top: 1.5px solid var(--fn-forest); }
.fn-section-heading > * { margin: 0; }
.fn-section-title { font-size: clamp(40px, 4vw, 56px); line-height: 1; }
.fn-stories, .fn-stories .wp-block-post-template { margin: 0; }
.fn-stories .wp-block-post > * { margin: 0; }
.fn-stories .fn-card-image { margin-bottom: 22px; overflow: hidden; }
.fn-card-image img { display: block; width: 100%; height: auto; aspect-ratio: 3 / 2; object-fit: cover; transition: transform .4s ease; }
.fn-card-image a:hover img { transform: scale(1.03); }
.fn-stories .fn-card-category, .fn-article-category { font: 500 13px/1.4 var(--fn-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--fn-clay); }
.fn-stories .fn-card-category { margin-bottom: 10px; }
.fn-card-category a, .fn-article-category a { color: inherit; }
.fn-card-title { font-size: 30px; line-height: 1.1; letter-spacing: -.03em; }
.fn-card-title a:hover { text-decoration: underline; }
.fn-stories .fn-card-excerpt { margin-top: 12px; font-size: 16px; line-height: 1.6; color: var(--fn-stone); }
.fn-card-excerpt p { margin: 0; }
.fn-stories .fn-card-date { margin-top: 14px; font: 400 13px/1.4 var(--fn-mono); color: var(--fn-stone); }
/* Home: two stories, then three */
.fn-stories--front .wp-block-post-template.is-layout-grid { grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 72px 32px; }
.fn-stories--front .wp-block-post { grid-column: span 2; }
.fn-stories--front .wp-block-post:nth-child(-n+2) { grid-column: span 3; }
.fn-stories--front .wp-block-post:nth-child(-n+2) .fn-card-title { font-size: clamp(32px, 3vw, 42px); }
/* Journal: one story per row, photograph left, words right */
.fn-stories--list .wp-block-post-template.is-layout-grid { grid-template-columns: minmax(0, 1fr); gap: 0; }
.fn-stories--list .wp-block-post { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); grid-template-rows: 1fr repeat(4, auto) 1fr; column-gap: 56px; padding: 48px 0; border-top: 1px solid var(--fn-line); }
.fn-stories--list .wp-block-post:first-child { border-top: 1.5px solid var(--fn-forest); }
.fn-stories--list .wp-block-post > * { grid-column: 2; }
.fn-stories--list .fn-card-image { grid-column: 1; grid-row: 1 / -1; margin: 0; }
.fn-stories--list .fn-card-category { grid-row: 2; }
.fn-stories--list .fn-card-title { grid-row: 3; font-size: clamp(34px, 3.4vw, 48px); }
.fn-stories--list .fn-card-excerpt { grid-row: 4; font-size: 18px; }
.fn-stories--list .fn-card-date { grid-row: 5; }

/* Home: the journal's idea, full width */
.fn-band { background: var(--fn-moss); padding: 120px var(--fn-gutter); text-align: center; }
.fn-band > * { margin: 0 auto; }
.fn-band-title { font-size: clamp(48px, 5.8vw, 88px); line-height: .96; letter-spacing: -.04em; }
.fn-band .fn-band-text { max-width: 32em; margin-top: 32px; font-size: 19px; line-height: 1.65; color: var(--fn-stone); }
.fn-band .fn-text-link { margin-top: 36px; }

/* Footer */
.fn-footer { margin: 0; padding: 104px 0 32px; background: var(--fn-deep); color: var(--fn-paper); }
.fn-footer > .fn-shell { container-type: inline-size; }
.fn-footer a { color: var(--fn-paper); }
.fn-footer-top { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); align-items: end; gap: 40px 64px; }
.fn-footer-top > *, .fn-footer-intro > * { margin: 0; }
.fn-footer-title { font-size: clamp(48px, 5.4vw, 80px); line-height: .96; letter-spacing: -.04em; color: var(--fn-paper); }
.fn-footer-title em { color: var(--fn-clay-light); }
.fn-footer-intro > p { max-width: 26em; font-size: 17px; line-height: 1.65; color: var(--fn-mist); }
.fn-footer-intro .wp-block-buttons { margin-top: 28px; }
.fn-light-button .wp-block-button__link { background: var(--fn-paper); color: var(--fn-forest); }
.fn-light-button .wp-block-button__link:hover { background: var(--fn-moss); }
/* The journal's name, set as wide as the page, like the nameplate on a printed issue */
.fn-footer .fn-nameplate { margin: 112px 0 0; font: 400 13.4cqi/.78 var(--fn-serif); letter-spacing: -.055em; white-space: nowrap; color: var(--fn-paper); }
.fn-footer-bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px 32px; margin-top: 40px; padding-top: 24px; border-top: 1px solid #f7f5ed33; }
.fn-footer-bottom > * { margin: 0; }
.fn-footer-links { display: flex; gap: 28px; font-size: 15px; font-weight: 600; }
.fn-footer-credit { font-size: 15px; color: var(--fn-mist); }
.fn-footer-credit a { color: var(--fn-mist); text-decoration: underline; }

/* Page headings */
.fn-page-heading { padding: 88px 0 72px; }
.fn-page-heading > * { margin: 0; }
.fn-page-title { font-size: clamp(56px, 7.2vw, 112px); line-height: .94; letter-spacing: -.045em; }
.fn-page-title em { font-style: italic; }
.fn-page-heading .fn-page-intro { max-width: 32em; margin-top: 28px; font-size: 20px; line-height: 1.6; color: var(--fn-stone); }
.fn-page-heading .wp-block-buttons { margin-top: 36px; }
.fn-journal-grid { padding-bottom: 120px; }
.fn-journal-grid .wp-block-query-pagination { margin-top: 40px; }
.fn-not-found { min-height: 520px; }

/* Copy this site, on the homepage and its own page: the commands on the left, the browser on the right */
.fn-copy { padding-bottom: 128px; scroll-margin-top: 32px; }
.fn-reprint-page { padding-bottom: 128px; }
.fn-try { display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: 32px; align-items: start; }
.fn-try > *, .fn-choice > * { margin: 0; }
.fn-choice-title { font-size: 34px; line-height: 1.1; }
.fn-choice .fn-choice-need { margin-top: 8px; font-size: 17px; color: var(--fn-stone); }
.fn-choice .fn-terminal { margin-top: 24px; }
.fn-choice { padding: 32px; background: var(--fn-moss); }
.fn-choice .wp-block-buttons { margin-top: 24px; }
.fn-choice .fn-pending { margin-top: 18px; padding-left: 16px; border-left: 3px solid var(--fn-clay); font-size: 16px; line-height: 1.6; color: var(--fn-stone); }
.fn-terminal { background: var(--fn-deep); color: var(--fn-paper); padding-bottom: 24px; }
.fn-terminal > * { margin: 0; }
.fn-terminal .fn-terminal-bar { padding: 12px 24px; background: #2b4a3d; font-size: 13px; font-weight: 600; line-height: 1.2; color: var(--fn-mist); }
.fn-terminal .fn-terminal-say { padding: 22px 24px 4px; font-size: 14px; font-weight: 500; color: var(--fn-mist); }
/* A drag across the commands selects and copies only the commands */
.fn-terminal .fn-terminal-bar, .fn-terminal .fn-terminal-say { -webkit-user-select: none; user-select: none; }
.fn-terminal .fn-cli-command { margin: 0; padding: 0 24px; overflow-x: auto; border: 0; border-radius: 0; background: none; color: var(--fn-paper); font: 400 14px/1.75 var(--fn-mono); }
.fn-terminal .fn-cli-command code { white-space: pre; font: inherit; }

/* About */
.fn-about-page { padding-bottom: 128px; }
.fn-about-page-grid { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); align-items: center; gap: 72px; margin: 0 0 120px; }
.fn-about-page-grid > *, .fn-about-page-copy > * { margin: 0; }
.fn-about-page-image img { display: block; width: 100%; height: 560px; object-fit: cover; }
.fn-about-page-copy h2 { font-size: clamp(36px, 3.4vw, 48px); line-height: 1.02; }
.fn-about-page-copy p { margin-top: 20px; font-size: 18px; line-height: 1.7; color: var(--fn-stone); }
.fn-photo-credits { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); grid-template-rows: auto 1fr; gap: 0 72px; padding-top: 28px; border-top: 1.5px solid var(--fn-forest); }
.fn-photo-credits > * { margin: 0; grid-column: 1; }
.fn-photo-credits h2 { font-size: clamp(36px, 3.4vw, 48px); line-height: 1.02; }
.fn-photo-credits > p { margin-top: 20px; font-size: 17px; line-height: 1.7; color: var(--fn-stone); }
.fn-photo-credits a { text-decoration: underline; }
.fn-photo-credits ul { grid-column: 2; grid-row: 1 / span 2; margin: 0; padding: 0; list-style: none; }
.fn-photo-credits li { padding: 16px 0; border-bottom: 1px solid var(--fn-line); font-size: 17px; }
.fn-photo-credits li:first-child { padding-top: 4px; }

/* Story */
.fn-article { padding: 28px 0 120px; }
.fn-article > * { margin: 0; }
.fn-back-link { font-size: 15px; font-weight: 600; }
.fn-back-link a:hover { color: var(--fn-clay); text-decoration: none; }
.fn-article .fn-article-head { max-width: 960px; margin: 48px auto 64px; text-align: center; }
.fn-article-head > * { margin: 0; }
.fn-article-head .fn-article-title { margin-top: 20px; font-size: clamp(52px, 6.6vw, 100px); line-height: .96; letter-spacing: -.045em; }
.fn-article-head .fn-article-deck { max-width: 34em; margin: 28px auto 0; font-size: 21px; line-height: 1.55; color: var(--fn-stone); }
.fn-article-deck p { margin: 0; }
.fn-article-head .fn-article-byline { margin-top: 28px; gap: 16px; }
.fn-article-byline > * { margin: 0; font: 400 13px/1.4 var(--fn-mono); color: var(--fn-stone); }
.fn-article-byline > * + *::before { content: "·"; margin-right: 16px; }
.fn-article-image img { display: block; width: 100%; height: auto; aspect-ratio: 2 / 1; object-fit: cover; }
.fn-article .fn-article-copy { max-width: 680px; margin: 80px auto 0; }
.fn-article-copy p { font-family: var(--fn-serif); font-size: 20px; line-height: 1.7; }
.fn-article-copy .fn-lede { font-size: 24px; line-height: 1.6; }
.fn-article-copy .has-drop-cap:not(:focus)::first-letter { margin: .08em .12em 0 0; font-size: 3.6em; font-weight: 500; line-height: .8; color: var(--fn-clay); }
.fn-article-copy h2 { margin-top: 64px; font-size: 36px; line-height: 1.1; }
.fn-article-copy .fn-quote { margin: 56px 0; padding: 4px 0 4px 28px; border-left: 3px solid var(--fn-clay); }
.fn-article-copy .fn-quote p { font-style: italic; font-size: 32px; line-height: 1.35; letter-spacing: -.015em; margin: 0; }
.fn-article-copy .fn-try-note { margin-top: 64px; padding: 32px 36px; background: var(--fn-moss); }
.fn-try-note > * { margin: 0; }
.fn-article-copy .fn-try-note h2 { margin: 0 0 12px; font-size: 28px; }
.fn-article-copy .fn-photo-credit { margin-top: 48px; font-family: inherit; font-size: 15px; color: var(--fn-stone); }
.fn-article-copy .fn-photo-credit a { text-decoration: underline; }
.fn-article-copy .wp-block-gallery.has-nested-images figure.wp-block-image { flex-direction: column; }
.fn-article-copy .wp-block-gallery.has-nested-images figure.wp-block-image img { height: auto; aspect-ratio: 4 / 3; }
.fn-article-copy .wp-block-gallery.has-nested-images figure.wp-block-image figcaption { position: static; padding: 10px 0 0; max-height: none; background: none; color: var(--fn-stone); font-size: 14px; text-align: left; }
.fn-story-navigation { margin-top: 80px; padding-top: 28px; border-top: 1px solid var(--fn-line); font-size: 16px; font-weight: 600; }
.fn-story-navigation > * { max-width: 45%; }

/* Below this width the long pull command no longer fits beside the browser card */
@media (max-width: 1260px) {
  .fn-try { grid-template-columns: minmax(0, 1fr); gap: 24px; }
}
@media (max-width: 1000px) {
  :root { --fn-gutter: 32px; }
  .fn-hero { gap: 40px; }
  .fn-stories--list .wp-block-post { column-gap: 36px; }
  .fn-about-page-grid { gap: 48px; }
}
@media (max-width: 900px) {
  .fn-hero { grid-template-columns: minmax(0, 1fr); padding-top: 32px; }
  .fn-hero-image.wp-block-image { margin-inline: calc(-1 * var(--fn-gutter)); }
  .fn-hero-image.wp-block-image img { height: auto; aspect-ratio: 4 / 5; }
  .fn-footer-top, .fn-about-page-grid { grid-template-columns: minmax(0, 1fr); }
  .fn-about-page-image img { height: auto; aspect-ratio: 3 / 2; }
}
@media (max-width: 760px) {
  .fn-stories--front .wp-block-post-template.is-layout-grid { grid-template-columns: minmax(0, 1fr); gap: 56px; }
  .fn-stories--front .wp-block-post, .fn-stories--front .wp-block-post:nth-child(-n+2) { grid-column: auto; }
  .fn-stories--list .wp-block-post { display: block; padding: 40px 0; }
  .fn-stories--list .fn-card-image { margin-bottom: 22px; }
  .fn-photo-credits { display: block; }
  .fn-photo-credits ul { margin-top: 28px; }
  /* Below about 745px the name and the three links no longer fit on one row, so the menu folds into its button */
  .fn-nav .wp-block-navigation__responsive-container:not(.is-menu-open) { display: none; }
  .fn-nav .wp-block-navigation__responsive-container-open { display: flex; padding: 10px; margin-right: -10px; }
  .fn-nav .wp-block-navigation__responsive-container-close { padding: 10px; }
  .fn-nav .wp-block-navigation__responsive-container.is-menu-open { background: var(--fn-paper); color: var(--fn-forest); padding: 28px; }
  .fn-nav .wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__container { gap: 28px; font-size: 22px; }
  .fn-nav .wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item:last-child a { padding: 12px 20px; }
}
@media (max-width: 700px) {
  :root { --fn-gutter: 20px; }
  .fn-header { min-height: 76px; }
  /* Keeps the name on one line beside the menu button down to 340px */
  .fn-wordmark { font-size: clamp(22px, 6.6vw, 28px); }
  .fn-mark { font-size: 30px; }
  .fn-hero { gap: 36px; padding: 28px 0 80px; }
  .fn-hero-title { font-size: clamp(52px, 15vw, 72px); }
  .fn-hero-copy .fn-hero-description { margin-top: 24px; font-size: 18px; }
  .fn-hero-copy .fn-actions { margin-top: 28px; }
  .fn-hero-image .wp-element-caption { padding: 14px 20px; }
  .fn-hero-image .wp-element-caption a { font-size: 20px; }
  .fn-front { padding-bottom: 88px; }
  .fn-section-heading { display: block; margin-bottom: 36px; }
  .fn-section-heading .fn-text-link { margin-top: 16px; }
  .fn-stories--front .wp-block-post:nth-child(-n+2) .fn-card-title, .fn-card-title, .fn-stories--list .fn-card-title { font-size: 32px; }
  .fn-stories--list .fn-card-excerpt { font-size: 16px; }
  .fn-band { padding-block: 80px; }
  .fn-band .fn-band-text { font-size: 17px; }
  .fn-footer { padding-top: 72px; }
  .fn-footer .fn-nameplate { margin-top: 72px; }
  .fn-footer-bottom { flex-direction: column; }
  .fn-page-heading { padding: 48px 0 44px; }
  .fn-page-heading .fn-page-intro { margin-top: 20px; font-size: 18px; }
  .fn-copy, .fn-journal-grid, .fn-reprint-page, .fn-about-page { padding-bottom: 80px; }
  .fn-choice-title { font-size: 30px; }
  .fn-choice { padding: 24px 20px; }
  .fn-terminal .fn-cli-command { font-size: 13px; padding-inline: 20px; }
